var i=`0656-efo-riro`;var n=`world-0656`;var s=`NG`;var a=`western-africa`;var r=4;var o=61;var l={en:`Efo Riro`,ua:`Ефо ріро`};var g={en:`Efo Riro is a Nigeria classic prepared with yellow onion, red bell pepper, scotch bonnet pepper, beef chuck. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Ефо ріро, страва кухні країни Нігерія зі складниками: жовта цибуля, червоний солодкий перець, перець скотч-боннет, яловича лопатка. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var d=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 11 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 11 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:11,i:[[`yellow-onion`,160,`g`],[`red-palm-oil`,65,`ml`],[`red-bell-pepper`,260,`g`],[`scotch-bonnet-pepper`,1,`pcs`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 35 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 35 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:35,i:[[`beef-chuck`,480,`g`],[`beef-stock`,700,`ml`],[`crayfish`,110,`g`],[`dawadawa`,20,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 12 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 12 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:12,i:[[`spinach`,540,`g`],[`table-salt`,null,`to_taste`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`parsley`,15,`g`]]}];var h={slug:i,id:n,country:`NG`,region:a,servings:4,minutes:61,title:l,text:g,steps:d};export{s as country,h as default,n as id,o as minutes,a as region,r as servings,i as slug,d as steps,g as text,l as title};